import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadMysoreData(){const e=readFileSync(resolve(__dirname,"../../mysore-kingdom-explorer/mysore-data.js"),"utf-8");return new Function(e+"\nreturn { MYSORE_INFO, TIMELINE_DATA, RULERS_DATA, CONTRIBUTIONS_DATA, GALLERY_IMAGES, REFERENCES };")()}describe("Kingdom of Mysore Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadMysoreData()}),describe("MYSORE_INFO metadata",()=>{it("contains correct Kingdom of Mysore attributes",()=>{expect(e.MYSORE_INFO.id).toBe("mysore-kingdom"),expect(e.MYSORE_INFO.name).toBe("Kingdom of Mysore"),expect(e.MYSORE_INFO.dynasty).toContain("Wadiyar"),expect(e.MYSORE_INFO.period).toContain("1399")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.MYSORE_INFO.quickStats)).toBe(!0),expect(e.MYSORE_INFO.quickStats.length).toBe(6)})}),describe("TIMELINE_DATA & RULERS_DATA",()=>{it("contains milestone timeline items and key rulers including Tipu Sultan",()=>{expect(Array.isArray(e.TIMELINE_DATA)).toBe(!0),expect(e.TIMELINE_DATA.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.RULERS_DATA)).toBe(!0),expect(e.RULERS_DATA.length).toBeGreaterThanOrEqual(4)})}),describe("CONTRIBUTIONS_DATA",()=>{it("contains required contribution fields",()=>{expect(e.CONTRIBUTIONS_DATA.overview).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.militaryRocketry).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.architecture).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.industryAgriculture).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.cultureDasara).toBeDefined()})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});